class Solution {
    fun solution(babbling: Array<String>): Int {
        var answer: Int = 0
        val a = arrayOf("aya", "ye", "woo", "ma")

        for(i in babbling){
            var word = i
            for (j in a) {
                word = word.replace(j, " ")
            }
            if (word.replace(" ", "").isEmpty()) {
                answer++
            }
        }
        return answer
    }
}
